'use strict';
const KEY='amir-fitness-tracker-v1';
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=v=>Number.isFinite(Number(v))?Number(v):0;
const fmt=v=>new Intl.NumberFormat('en-US',{maximumFractionDigits:1}).format(num(v));
const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const shift=(date,n)=>{const d=new Date(date+'T12:00:00');d.setDate(d.getDate()+n);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const pretty=(date,opt={day:'numeric',month:'long',year:'numeric'})=>new Intl.DateTimeFormat('ar-EG-u-ca-gregory',opt).format(new Date(date+'T12:00:00'));
const uid=()=>globalThis.crypto?.randomUUID?.()||`${Date.now()}-${Math.random().toString(36).slice(2)}`;
const timeValid=t=>/^([01]\d|2[0-3]):[0-5]\d$/.test(t||'');
const defaults=()=>({version:2,goalWeight:null,targets:{calories:null,protein:null,carbs:null,fat:null,water:null,steps:null,workoutDays:null},measurements:[],workouts:[],meals:[],water:[],walking:[],dayNotes:{},nutritionPlan:null,reminders:{enabled:false,waterMinutes:90,mealTimes:['08:00','13:00','19:00'],quietStart:'22:30',quietEnd:'07:00'}});
function migrate(raw){const d=defaults();if(!raw||typeof raw!=='object'||Array.isArray(raw))throw Error('بيانات غير صالحة');for(const key of ['measurements','workouts','meals','water','walking']){if(raw[key]!=null&&!Array.isArray(raw[key]))throw Error('سجل غير صالح');d[key]=(raw[key]||[]).map(r=>({...r,id:r.id||uid()}))}return {...raw,...d,goalWeight:raw.goalWeight??null,targets:{...d.targets,...raw.targets},dayNotes:raw.dayNotes||{},nutritionPlan:raw.nutritionPlan??null,reminders:raw.reminders?{...d.reminders,...raw.reminders,mealTimes:Array.isArray(raw.reminders.mealTimes)?raw.reminders.mealTimes:d.reminders.mealTimes}:d.reminders}}
const PKEY='amir-fitness-tracker-profiles-v1';
const PALETTE=['lime','blue','orange','purple'];
function loadProfiles(){try{const raw=JSON.parse(localStorage.getItem(PKEY)||'null');if(raw&&Array.isArray(raw.list)&&raw.list.length&&raw.list.every(p=>p&&typeof p.id==='string'&&typeof p.name==='string')&&raw.list.some(p=>p.id===raw.activeId))return raw}catch{}const seed={list:[{id:'default',name:'أمير',color:'lime'}],activeId:'default'};localStorage.setItem(PKEY,JSON.stringify(seed));return seed}
let profiles=loadProfiles();
function saveProfiles(){localStorage.setItem(PKEY,JSON.stringify(profiles))}
function activeProfile(){return profiles.list.find(p=>p.id===profiles.activeId)||profiles.list[0]}
function storageKey(id){return id==='default'?KEY:`${KEY}::${id}`}
function loadData(){let failed=false,d;try{const raw=localStorage.getItem(storageKey(profiles.activeId));d=raw?migrate(JSON.parse(raw)):defaults();validate(d)}catch{d=defaults();failed=true}return {d,failed}}
let loadFailed=false,data;{const r=loadData();data=r.d;loadFailed=r.failed}
let selected=today(),view='today',range=7,editing=null,formKind='',toastTimer,timerEnd=0,timerHandle=null;
function notify(text,error=false){const el=$('#toast');el.textContent=text;el.className='toast'+(error?' error':'');el.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.hidden=true,5000)}

const paths={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z"/>',meal:'<path d="M4 3v6a3 3 0 0 0 6 0V3M7 3v18M20 21V3c-5 3-5 10 0 10"/>',water:'<path d="M12 3s-7 8-7 12a7 7 0 0 0 14 0c0-4-7-12-7-12Z"/>',walk:'<circle cx="14" cy="4" r="2"/><path d="m7 11 4-4 4 2 3 4h3M11 7l-2 8-4 6m4-6 5 2v5"/>',gym:'<path d="M7 9h10M7 15h10M3 8v8m4-11v14M21 8v8M17 5v14"/>',chart:'<path d="M4 3v17h17M8 15l4-5 4 2 5-7"/>',settings:'<path d="M4 7h16M4 17h16"/><circle cx="8" cy="7" r="3"/><circle cx="16" cy="17" r="3"/>',scale:'<rect x="4" y="3" width="16" height="18" rx="3"/><path d="M8 8a5 5 0 0 1 8 0M12 10l2-3"/>',plan:'<path d="M12 21c-4-2.5-8-6.2-8-11a5 5 0 0 1 8-4 5 5 0 0 1 8 4c0 4.8-4 8.5-8 11Z"/><path d="M12 12V8"/>'};
const icon=k=>`<svg class="ico" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[k]||paths.home}</svg>`;
const nav=[['today','home','يومي','نظرة على يومك'],['meals','meal','الوجبات','وجباتك اليومية'],['activity','walk','النشاط','المياه والمشي'],['workouts','gym','التمارين','سجل التمارين'],['nutrition','plan','الخطة الغذائية','نظامك الغذائي الذكي'],['progress','chart','التقدم','كل خطوة لها أثر'],['settings','settings','إعداداتي','أهدافك وإعداداتك']];
const equipmentLibrary=[
 {id:'barbell',name:'بار حر (Barbell)',group:'كامل الجسم',exercises:['ضغط بار مسطح (Bench Press)','ديدليفت (Deadlift)','سكوات بار (Back Squat)','ضغط عسكري بار (Overhead Press)','ركوع بار (Bent-over Row)']},
 {id:'dumbbell',name:'دمبل (Dumbbells)',group:'كامل الجسم',exercises:['ضغط دمبل مسطح','ضغط دمبل مائل','فرد جانبي للكتف (Lateral Raise)','ثني ذراع (Bicep Curl)','تمديد تراي خلف الرأس','رفعة روماني (RDL)','ركوع دمبل فردي (One-Arm Row)']},
 {id:'smith',name:'جهاز سميث (Smith Machine)',group:'رجل',exercises:['سكوات سميث','ضغط صدر سميث','اندفاع سميث (Lunge)','ضغط كتف سميث']},
 {id:'cable',name:'جهاز الكابلات (Cable Machine)',group:'ظهر',exercises:['تجديف كابل جالس (Seated Row)','سحب حبل ثلاثي (Tricep Pushdown)','فتح صدر كابل (Cable Fly)','سحب علوي حبل (Face Pull)','ثني كابل للباي (Cable Curl)']},
 {id:'lat',name:'جهاز اللات (Lat Pulldown)',group:'ظهر',exercises:['سحب لات أمامي','سحب لات خلفي','سحب بقبضة ضيقة']},
 {id:'chest-press',name:'جهاز ضغط الصدر (Chest Press Machine)',group:'صدر',exercises:['ضغط صدر آلة','فتح صدر آلة (Pec Deck)']},
 {id:'shoulder-press',name:'جهاز ضغط الكتف (Shoulder Press Machine)',group:'كتف',exercises:['ضغط كتف آلة']},
 {id:'leg-press',name:'جهاز ضغط الرجل (Leg Press)',group:'رجل',exercises:['ضغط رجل 45 درجة']},
 {id:'leg-extension',name:'جهاز الفخذ الأمامي (Leg Extension)',group:'رجل',exercises:['رفعة الفخذ الأمامي']},
 {id:'leg-curl',name:'جهاز الفخذ الخلفي (Leg Curl)',group:'رجل',exercises:['ثني الفخذ الخلفي جالس','ثني الفخذ الخلفي مستلقٍ']},
 {id:'assisted',name:'جهاز العقلة المساعد (Assisted Pull-up/Dip)',group:'ظهر',exercises:['عقلة مساعدة (Pull-up)','متوازي مساعد (Dip)']},
 {id:'ab-crunch',name:'جهاز البطن (Ab Crunch Machine)',group:'بطن',exercises:['كرانش آلة']},
 {id:'trx',name:'حلقات TRX',group:'كامل الجسم',exercises:['ضغط TRX','تجديف TRX','سكوات TRX']},
 {id:'kettlebell',name:'كيتل بيل (Kettlebell)',group:'كامل الجسم',exercises:['سوينغ كيتل بيل','سكوات كيتل بيل']},
 {id:'treadmill',name:'المشاية (Treadmill)',group:'كارديو',exercises:['مشي/جري على المشاية']},
 {id:'bike',name:'دراجة ثابتة (Bike)',group:'كارديو',exercises:['دراجة ثابتة']},
 {id:'elliptical',name:'إليبتيكال (Elliptical)',group:'كارديو',exercises:['إليبتيكال']},
 {id:'rowing',name:'جهاز التجديف (Rowing Machine)',group:'كارديو',exercises:['تجديف هوائي']},
 {id:'bodyweight',name:'وزن الجسم (بدون جهاز)',group:'كامل الجسم',exercises:['ضغط بار الجسم (Push-up)','عقلة (Pull-up)','سكوات وزن الجسم','بلانك (Plank)','برجات (Burpees)']},
 {id:'other',name:'جهاز آخر / غير مدرج',group:'أخرى',exercises:[]}
];
const equipmentName=id=>equipmentLibrary.find(e=>e.id===id)?.name||'';
const activityFactors={sedentary:1.2,light:1.375,moderate:1.55,active:1.725,veryActive:1.9};
const activityLabels={sedentary:'خامل (عمل مكتبي، بدون رياضة)',light:'نشاط خفيف (١-٣ أيام رياضة)',moderate:'نشاط متوسط (٣-٥ أيام رياضة)',active:'نشاط عالٍ (٦-٧ أيام رياضة)',veryActive:'نشاط عالٍ جدًا (رياضي/عمل بدني)'};
const goalLabels={cut:'تنشيف (خسارة دهون)',bulk:'تضخيم (زيادة كتلة عضلية)',maintain:'ثبات الوزن'};
function computePlan(p){const bmr=p.gender==='female'?10*p.weight+6.25*p.height-5*p.age-161:10*p.weight+6.25*p.height-5*p.age+5;const tdee=bmr*(activityFactors[p.activity]||1.55);const calories=Math.round(p.goal==='cut'?tdee*.8:p.goal==='bulk'?tdee*1.15:tdee);const protein=Math.round(p.weight*(p.goal==='cut'?2.2:p.goal==='bulk'?2:1.8));const fat=Math.round(calories*.25/9);const carbs=Math.max(0,Math.round((calories-protein*4-fat*9)/4));return {bmr:Math.round(bmr),tdee:Math.round(tdee),calories,protein,carbs,fat}}
const foodBank={
 cut:{breakfast:['بيض مسلوق + شوفان بالحليب خالي الدسم + فاكهة','زبادي يوناني + مكسرات قليلة + توت'],lunch:['صدر دجاج مشوي + أرز بني + سلطة خضار كبيرة','سمك مشوي + كينوا + خضار سوتيه'],dinner:['سلمون أو دجاج + خضار مشوي + كمية بسيطة كربوهيدرات','شوربة عدس + سلطة + بروتين خفيف'],snack:['زبادي بروتين + تفاحة','حفنة لوز + بروتين شيك']},
 bulk:{breakfast:['بيض كامل + خبز أسمر + زبدة فول سوداني + موز','شوفان بالحليب كامل الدسم + عسل + مكسرات'],lunch:['لحم أو دجاج + أرز أو معكرونة + خضار','فاهيتا لحم + أرز + أفوكادو'],dinner:['سمك أو لحم + بطاطا + خضار','لحم مفروم مشوي + أرز + سلطة'],snack:['شيك بروتين بالحليب كامل + موز','زبادي كامل الدسم + عسل + مكسرات']},
 maintain:{breakfast:['بيض + خبز أسمر + خضار','شوفان + فاكهة + مكسرات'],lunch:['دجاج أو سمك + أرز أو كينوا + خضار','سلطة كبيرة مع بروتين وكربوهيدرات معتدلة'],dinner:['بروتين خفيف + خضار + كمية معتدلة كربوهيدرات','شوربة + سلطة + بروتين'],snack:['فاكهة + مكسرات','زبادي يوناني']}
};
function samplePlan(goal,calories){const bank=foodBank[goal]||foodBank.maintain;return [['فطور',.25,'breakfast'],['غداء',.35,'lunch'],['عشاء',.25,'dinner'],['سناك',.15,'snack']].map(([label,share,key])=>({label,calories:Math.round(calories*share),options:bank[key]}))}
const byDate=(key,date=selected)=>data[key].filter(x=>x.date===date);
const totals=(date=selected)=>byDate('meals',date).reduce((s,m)=>{for(const k of ['calories','protein','carbs','fat'])s[k]+=num(m[k]);return s},{calories:0,protein:0,carbs:0,fat:0});
const waterTotal=(date=selected)=>byDate('water',date).reduce((a,x)=>a+num(x.ml),0);
const walkTotal=(date=selected)=>byDate('walking',date).reduce((a,x)=>({steps:a.steps+num(x.steps),minutes:a.minutes+num(x.minutes),distance:a.distance+num(x.distance)}),{steps:0,minutes:0,distance:0});
const pct=(n,t)=>t>0?Math.max(0,Math.min(100,n/t*100)):0;
const button=(label,action,secondary=false,extra='')=>`<button class="button ${secondary?'secondary':''}" data-action="${action}" ${extra}>${label}</button>`;
const empty=(text,action,label='إضافة الآن')=>`<div class="empty"><p>${text}</p>${action?button(label,action,true):''}</div>`;
const progress=(v,t)=>`<div class="progress" role="progressbar" aria-label="التقدم نحو الهدف" aria-valuenow="${Math.round(pct(v,t))}" aria-valuemin="0" aria-valuemax="100"><span style="width:${pct(v,t)}%"></span></div>`;
function stat(title,value,target,unit,color,ico,action,cta){return `<div class="stat ${color}"><div class="stat-top"><span>${title}</span><span class="icon-chip">${icon(ico)}</span></div><div class="stat-value">${fmt(value)} <small>${unit}</small></div>${progress(value,target)}<div class="stat-foot"><span>${target?`الهدف ${fmt(target)} ${unit}`:'لم تحدد هدفًا بعد'}</span>${target?`<span>${Math.round(pct(value,target))}%</span>`:''}</div><button class="text-button" data-action="${action}">${cta}</button></div>`}
function summary(){const t=totals(),w=walkTotal();return `<div class="stats">${stat('الوجبات والسعرات',t.calories,data.targets.calories,'سعرة','orange','meal','meal','+ تسجيل وجبة')}${stat('شرب المياه',waterTotal()/1000,num(data.targets.water)/1000,'لتر','blue','water','water250','+ كوب 250 مل')}${stat('خطوات المشي',w.steps,data.targets.steps,'خطوة','','walk','walking','تسجيل خطواتي')}${stat('تمارين المقاومة',byDate('workouts').length,null,'تمرين','purple','gym','workout','+ تسجيل تمرين')}</div>`}
const recordActions=(key,id,repeat=false)=>`<div class="actions"><button class="text-button" data-action="edit" data-key="${key}" data-id="${esc(id)}">تعديل</button>${repeat?`<button class="text-button" data-action="repeat" data-key="${key}" data-id="${esc(id)}">تكرار</button>`:''}<button class="text-button danger" data-action="delete" data-key="${key}" data-id="${esc(id)}" aria-label="حذف السجل">حذف</button></div>`;
function mealRecord(m){return `<article class="record"><div class="record-head"><div><h3>${esc(m.name)} <span class="sub">${esc(m.time||'')}</span></h3><p class="sub">${esc(m.food)}</p></div>${recordActions('meals',m.id,true)}</div><div class="chips"><span class="chip">${fmt(m.calories)} سعرة</span><span class="chip">بروتين ${fmt(m.protein)} غ</span><span class="chip">كارب ${fmt(m.carbs)} غ</span><span class="chip">دهون ${fmt(m.fat)} غ</span>${m.grams?`<span class="chip">${fmt(m.grams)} غ طعام</span>`:''}</div></article>`}
function workoutRecord(w){return `<article class="record"><div class="record-head"><div><h3>${esc(w.exercise)}</h3><p class="sub">${esc(w.group)}${w.equipment?` · ${esc(equipmentName(w.equipment))}`:''} · ${pretty(w.date)}${w.duration?` · ${fmt(w.duration)} دقيقة`:''}</p></div>${recordActions('workouts',w.id,true)}</div><div class="chips">${(w.sets||[]).map((s,i)=>`<span class="chip big">${i+1} <bdi>${fmt(s.w)} kg × ${fmt(s.r)}</bdi></span>`).join('')}</div>${w.notes?`<p class="sub">${esc(w.notes)}</p>`:''}</article>`}
function renderNutrition(){const np=data.nutritionPlan,has=np&&np.calories;return `<div class="daily-banner"><div><h2>خطتك الغذائية الذكية</h2><p>${has?`آخر تحديث ${pretty(np.generatedAt||today())} — ${goalLabels[np.goal]||''}`:'أدخل بياناتك لتوليد نظام غذائي كامل بالسعرات والماكروز، واختر تنشيف أو تضخيم أو ثبات.'}</p></div>${button(has?'تحديث بياناتي':'إنشاء خطتي','nutrition')}</div>${has?`<div class="stats">${stat('السعرات المقترحة',np.calories,np.calories,'سعرة','orange','plan','nutrition','تعديل البيانات')}${stat('البروتين',np.protein,np.protein,'غ','','plan','nutrition','تعديل البيانات')}${stat('الكربوهيدرات',np.carbs,np.carbs,'غ','blue','plan','nutrition','تعديل البيانات')}${stat('الدهون',np.fat,np.fat,'غ','purple','plan','nutrition','تعديل البيانات')}</div><div class="card"><div class="card-head"><h2>ملخص الحساب</h2></div><div class="mini-grid"><div class="mini"><small>معدل الأيض الأساسي BMR</small><strong>${fmt(np.bmr)} <small>سعرة</small></strong></div><div class="mini"><small>احتياجك اليومي TDEE</small><strong>${fmt(np.tdee)} <small>سعرة</small></strong></div><div class="mini"><small>هدفك الحالي</small><strong>${goalLabels[np.goal]||'—'}</strong></div></div><button class="button" data-action="applyNutrition">تطبيق كهدف يومي في الوجبات</button></div><div class="grid-two">${samplePlan(np.goal,np.calories).map(m=>`<div class="card"><h2>${m.label} <span class="sub">~${fmt(m.calories)} سعرة</span></h2><ul class="plan-list">${m.options.map(o=>`<li>${esc(o)}</li>`).join('')}</ul></div>`).join('')}</div><p class="notice">هذه أرقام تقديرية بمعادلة Mifflin-St Jeor، نقطة بداية علمية وليست بديلاً عن استشارة أخصائي تغذية عند وجود حالة صحية خاصة.</p>`:empty('لم يتم إنشاء خطة بعد. أدخل الجنس والعمر والطول والوزن ومستوى النشاط وهدفك (تنشيف / تضخيم / ثبات).','nutrition','إنشاء خطتي')}`}
function renderToday(){const t=totals(),meals=byDate('meals'),workouts=byDate('workouts'),w=walkTotal(),configured=data.targets.water&&data.targets.steps;return `<div class="daily-banner"><div><h2>${selected===today()?'أهلًا أمير، خلّي كل يوم محسوب.':pretty(selected)}</h2><p>${configured?'سجّل يومك وشاهد تقدمك في مكان واحد.':'ابدأ بتحديد أهداف المياه والمشي والتغذية المناسبة لك.'}</p></div>${button(configured?'راجع أهدافك':'حدد أهدافك','settings')}</div>${summary()}<div class="grid-two"><div class="card"><div class="card-head"><h2>وجبات اليوم</h2>${button('+ وجبة','meal',true)}</div>${meals.length?meals.map(mealRecord).join(''):empty('ابدأ بوجبتك الأولى، وأضف قيمها الغذائية.','meal','تسجيل وجبة')}<div class="mini-grid">${[['بروتين',t.protein,'protein'],['كربوهيدرات',t.carbs,'carbs'],['دهون',t.fat,'fat']].map(([label,v,k])=>`<div class="mini"><small>${label}</small><strong>${fmt(v)} <small>غ</small></strong>${progress(v,data.targets[k])}</div>`).join('')}</div></div><div><div class="card water-panel"><div class="card-head"><h2>كوب جديد، تقدم جديد</h2>${icon('water')}</div><div class="water-number">${fmt(waterTotal()/1000)} <small>لتر ${data.targets.water?`من ${fmt(data.targets.water/1000)}`:''}</small></div><div class="quick-buttons">${button('+ 250 مل','water250')}${button('+ 500 مل','water500')}${button('كمية أخرى','water',true)}</div></div><div class="card"><div class="card-head"><h2>تمارين اليوم</h2>${icon('gym')}</div>${workouts.length?workouts.slice(0,2).map(workoutRecord).join(''):empty('يوم التمرين؟ سجّل أوزانك وعداتك هنا.','workout','أضف تمرينًا')}${workouts.length>2?'<a class="text-button" href="#workouts">عرض كل التمارين</a>':''}</div></div></div><div class="card"><div class="card-head"><div><h2>ملاحظات اليوم</h2><p class="sub">طاقة اليوم، النوم أو ملاحظة تساعدك في المتابعة</p></div>${button('تعديل','note',true)}</div><p>${esc(data.dayNotes[selected]||'لا توجد ملاحظات لهذا اليوم.')}</p></div>`}
function renderMeals(){const t=totals(),arr=byDate('meals');const recent=[...data.meals].reverse().filter((m,i,a)=>a.findIndex(x=>x.food===m.food&&x.name===m.name)===i).slice(0,5);return `<div class="section-head"><div><h2>سجل الوجبات</h2><p class="sub">اختر اليوم بالأعلى لمراجعة سجله.</p></div>${button('+ إضافة وجبة','meal')}</div><div class="stats">${[['السعرات','calories','سعرة','orange'],['البروتين','protein','غ',''],['الكربوهيدرات','carbs','غ','blue'],['الدهون','fat','غ','purple']].map(([l,k,u,c])=>stat(l,t[k],data.targets[k],u,c,'meal','settings','تعديل الهدف')).join('')}</div><div class="grid-two"><div class="card"><div class="card-head"><h2>وجبات ${pretty(selected,{day:'numeric',month:'long'})}</h2><span class="sub">${arr.length} وجبات</span></div>${arr.length?arr.map(mealRecord).join(''):empty('لا توجد وجبات مسجلة في هذا التاريخ.','meal')}</div><div class="card"><h2>كرر وجبة سابقة</h2><p class="sub">تُفتح نسخة قابلة للتعديل في اليوم المحدد.</p>${recent.length?recent.map(m=>`<div class="record"><h3>${esc(m.name)}</h3><p class="sub">${esc(m.food)}</p><button class="text-button" data-action="repeat" data-key="meals" data-id="${esc(m.id)}">+ أضف لليوم المحدد</button></div>`).join(''):empty('وجباتك السابقة ستظهر هنا.')}<p class="notice">أدخل القيم من ملصق الطعام أو مصدر تثق به. السعرات والماكروز تخص كامل الكمية المسجلة؛ تعديل وزن الطعام لا يحسبها تلقائيًا.</p></div></div>`}
function renderActivity(){const water=byDate('water'),walk=walkTotal();return `<div class="grid-two"><div><div class="card water-panel"><div class="card-head"><h2>شرب المياه</h2>${icon('water')}</div><div class="water-number">${fmt(waterTotal()/1000)} <small>لتر</small></div><p class="sub">${data.targets.water?`هدفك ${fmt(data.targets.water/1000)} لتر · المتبقي ${fmt(Math.max(0,data.targets.water-waterTotal()))} مل`:'حدد هدف المياه من الإعدادات.'}</p>${progress(waterTotal(),data.targets.water)}<div class="quick-buttons">${button('+ 250 مل','water250')}${button('+ 500 مل','water500')}${button('كمية أخرى','water',true)}</div></div><div class="card"><h2>سجل المياه</h2>${water.length?water.map(x=>`<div class="record"><div class="record-head"><div><h3>${fmt(x.ml)} مل</h3><p class="sub">${esc(x.time||'')}</p></div>${recordActions('water',x.id)}</div></div>`).join(''):empty('لم تسجل مياه في هذا اليوم.')}</div></div><div><div class="card"><div class="card-head"><h2>هدف المشي</h2>${icon('walk')}</div><div class="stat-value">${fmt(walk.steps)} <small>خطوة</small></div><p class="sub">${data.targets.steps?`المتبقي ${fmt(Math.max(0,data.targets.steps-walk.steps))} من هدف ${fmt(data.targets.steps)}`:'حدد عدد الخطوات المستهدف في الإعدادات.'}</p><div style="margin:18px 0">${progress(walk.steps,data.targets.steps)}</div><div class="mini-grid"><div class="mini"><small>المدة</small><strong>${fmt(walk.minutes)} <small>د</small></strong></div><div class="mini"><small>المسافة</small><strong>${fmt(walk.distance)} <small>كم</small></strong></div><div class="mini"><small>من الهدف</small><strong>${Math.round(pct(walk.steps,data.targets.steps))}%</strong></div></div>${button('تسجيل إجمالي اليوم','walking')}<p class="notice">انقل إجمالي خطوات اليوم من هاتفك أو ساعتك. حفظ الإجمالي يستبدل قراءة اليوم السابقة لتجنب احتساب الخطوات مرتين.</p></div>${byDate('walking').map(x=>`<div class="card"><h3>قراءة يوم ${pretty(x.date)}</h3><p class="sub">${fmt(x.steps)} خطوة · ${fmt(x.minutes)} دقيقة · ${fmt(x.distance)} كم</p>${recordActions('walking',x.id)}</div>`).join('')}</div></div>`}
function renderWorkouts(){const trainingWeek=Array.from({length:7},(_,i)=>shift(selected,i-6));const trainingCount=trainingWeek.filter(d=>byDate('workouts',d).length).length;const arr=byDate('workouts'),sets=arr.reduce((a,w)=>a+w.sets.length,0),volume=arr.reduce((a,w)=>a+w.sets.reduce((b,s)=>b+num(s.w)*num(s.r),0),0),recent=[...data.workouts].sort((a,b)=>b.date.localeCompare(a.date)).filter((w,i,a)=>a.findIndex(x=>x.exercise===w.exercise)===i).slice(0,6);return `<div class="daily-banner"><div><h2>${trainingCount} أيام تمرين في آخر ٧ أيام</h2><p>${data.targets.workoutDays?`هدفك ${data.targets.workoutDays} أيام أسبوعيًا`:'حدد عدد أيام التمرين الأسبوعية من الإعدادات.'}</p></div>${button('الهدف الأسبوعي','settings',true)}</div><div class="section-head"><div><h2>كل جولة لها سجل</h2><p class="sub">٣ جولات افتراضيًا، والجولة الرابعة اختيارية.</p></div>${button('+ إضافة تمرين','workout')}</div><div class="mini-grid"><div class="mini"><small>تمارين اليوم</small><strong>${arr.length}</strong></div><div class="mini"><small>الجولات المسجلة</small><strong>${sets}</strong></div><div class="mini"><small>إجمالي الوزن × العدات</small><strong>${fmt(volume)} <small>كجم</small></strong></div></div><div class="grid-two"><div class="card">${arr.length?arr.map(workoutRecord).join(''):empty('لا يوجد تمرين مسجل لهذا اليوم.','workout')}</div><div><div class="card"><h2>راحة بين الجولات</h2><p class="sub">المؤقت يعمل أثناء فتح التطبيق.</p><div class="timer-box"><strong class="timer" id="timer">${timerText()}</strong><div class="actions">${button('60 ثانية','timer60',true)}${button('90 ثانية','timer90',true)}<button class="text-button" data-action="timerStop">إيقاف</button></div></div></div><div class="card"><h2>من آخر تمارينك</h2><p class="sub">استرجع الأوزان السابقة وعدّلها لجلسة جديدة.</p>${recent.length?recent.map(w=>`<div class="record"><h3>${esc(w.exercise)}</h3><p class="sub">${pretty(w.date)} · ${w.sets.map(s=>`${fmt(s.w)} × ${fmt(s.r)}`).join(' / ')}</p><button class="text-button" data-action="repeat" data-key="workouts" data-id="${esc(w.id)}">استخدم لليوم المحدد</button></div>`).join(''):empty('تمارينك السابقة ستظهر هنا.')}</div></div></div>`}
function weightChart(arr){if(arr.length<2)return empty('أضف قياسين على الأقل لعرض اتجاه الوزن.','measurement','تسجيل وزن');const a=arr.slice(-15),min=Math.min(...a.map(x=>num(x.weight)))-.5,max=Math.max(...a.map(x=>num(x.weight)))+.5;const points=a.map((x,i)=>({x:35+i*630/(a.length-1),y:135-(num(x.weight)-min)/(max-min)*105,d:x}));return `<svg viewBox="0 0 700 180" class="chart" role="img" aria-label="تطور الوزن؛ جميع القيم والتواريخ موضحة في جدول القياسات"><path class="chart-grid" d="M35 30H665M35 82H665M35 135H665"/><polyline class="chart-line" points="${points.map(p=>`${p.x},${p.y}`).join(' ')}"/>${points.map(p=>`<circle class="chart-point" cx="${p.x}" cy="${p.y}" r="5"><title>${esc(p.d.date)}: ${fmt(p.d.weight)} كجم</title></circle>`).join('')}<text x="35" y="165" text-anchor="start">${esc(a[0].date)}</text><text x="665" y="165" text-anchor="end">${esc(a.at(-1).date)}</text><text x="35" y="18">${fmt(max)} kg</text></svg>`}
function renderProgress(){const dates=Array.from({length:range},(_,i)=>shift(selected,i-range+1)),active=dates.filter(d=>byDate('workouts',d).length).length,waterDays=data.targets.water?dates.filter(d=>waterTotal(d)>=data.targets.water).length:null,stepDays=data.targets.steps?dates.filter(d=>walkTotal(d).steps>=data.targets.steps).length:null,measurements=[...data.measurements].sort((a,b)=>a.date.localeCompare(b.date)),last=measurements.at(-1),first=measurements[0],weekly=Array.from({length:7},(_,i)=>shift(selected,i-6)),max=Math.max(1,...weekly.map(d=>walkTotal(d).steps));return `<div class="section-head"><div><h2>تقرير المتابعة</h2><p class="sub">${pretty(dates[0])} — ${pretty(selected)}</p></div><div class="range-buttons">${[7,30].map(n=>`<button class="button secondary ${range===n?'active':''}" data-action="range" data-range="${n}">${n} أيام</button>`).join('')}</div></div><div class="mini-grid"><div class="mini"><small>أيام تمارين المقاومة</small><strong>${active} <small>/ ${range}</small></strong></div><div class="mini"><small>أيام تحقيق هدف المياه الحالي</small><strong>${waterDays??'—'}</strong></div><div class="mini"><small>أيام تحقيق هدف الخطوات الحالي</small><strong>${stepDays??'—'}</strong></div></div><div class="grid-two"><div class="card"><div class="card-head"><h2>تطور الوزن</h2>${button('+ قياس','measurement',true)}</div><div class="mini-grid"><div><p class="sub">آخر قياس</p><h2>${last?fmt(last.weight):'—'} <small class="sub">كجم</small></h2></div><div><p class="sub">من أول قياس</p><h2>${last&&measurements.length>1?`${last.weight-first.weight>0?'+':''}${fmt(last.weight-first.weight)}`:'—'}</h2></div><div><p class="sub">هدف الوزن</p><h2>${data.goalWeight?fmt(data.goalWeight):'—'}</h2></div></div>${weightChart(measurements)}</div><div class="card"><h2>خطوات آخر ٧ أيام</h2><div class="week-bars">${weekly.map(d=>`<div class="bar-col"><b>${fmt(walkTotal(d).steps)}</b><span style="height:${walkTotal(d).steps/max*120}px"></span>${pretty(d,{weekday:'short'})}</div>`).join('')}</div></div></div><div class="card"><h2>السجل اليومي</h2><p class="sub">الشرطة تعني عدم وجود تسجيل؛ لا تعني صفرًا فعليًا.</p><div class="table-wrap"><table><thead><tr><th>التاريخ</th><th>السعرات</th><th>بروتين غ</th><th>مياه مل</th><th>خطوات</th><th>تمارين</th></tr></thead><tbody>${[...dates].reverse().map(d=>`<tr><td><button class="text-button" data-action="date" data-date="${d}">${pretty(d,{day:'numeric',month:'short'})}</button></td><td>${byDate('meals',d).length?fmt(totals(d).calories):'—'}</td><td>${byDate('meals',d).length?fmt(totals(d).protein):'—'}</td><td>${byDate('water',d).length?fmt(waterTotal(d)):'—'}</td><td>${byDate('walking',d).length?fmt(walkTotal(d).steps):'—'}</td><td>${byDate('workouts',d).length||'—'}</td></tr>`).join('')}</tbody></table></div></div><div class="card"><div class="card-head"><h2>سجل قياسات الجسم</h2>${button('قياس جديد','measurement',true)}</div>${measurements.length?[...measurements].reverse().map(m=>`<div class="record"><div class="record-head"><div><h3>${fmt(m.weight)} كجم</h3><p class="sub">${pretty(m.date)}</p></div>${recordActions('measurements',m.id)}</div><div class="chips">${[['bmi','BMI'],['bfr','دهون %'],['fatMass','كتلة الدهون كجم'],['muscleWeight','عضلات كجم'],['water','ماء %'],['bmr','BMR'],['visceralFat','دهون حشوية'],['leanWeight','وزن دون دهون كجم']].filter(([k])=>m[k]!=null).map(([k,l])=>`<span class="chip">${l}: ${fmt(m[k])}</span>`).join('')}</div></div>`).join(''):empty('ابدأ بتسجيل وزنك. باقي قياسات الجسم اختيارية.','measurement')}</div>`}
const goalFields=[['goalWeight','هدف الوزن (كجم)'],['calories','السعرات اليومية'],['protein','البروتين (غ)'],['carbs','الكربوهيدرات (غ)'],['fat','الدهون (غ)'],['water','المياه اليومية (مل)'],['steps','الخطوات اليومية'],['workoutDays','أيام التمرين أسبوعيًا']];
function renderSettings(){const rm=data.reminders;return `<div class="settings-grid"><div class="card"><div class="card-head"><h2>أهدافك الشخصية</h2>${button('تعديل','goals',true)}</div>${goalFields.map(([k,l])=>`<div class="goal-row"><span>${l}</span><strong>${(k==='goalWeight'?data.goalWeight:data.targets[k])?fmt(k==='goalWeight'?data.goalWeight:data.targets[k]):'لم يُحدد'}</strong></div>`).join('')}<p class="notice">اختر أهدافك بنفسك وفق خطتك، أو استخدم صفحة «الخطة الغذائية» لحساب سعرات وماكروز مقترحة تلقائيًا.</p></div><div class="card"><div class="card-head"><h2>تذكيرات المياه والطعام</h2>${button('تعديل','reminders',true)}</div><div class="goal-row"><span>الحالة</span><strong>${rm.enabled?'مفعّلة':'متوقفة'}</strong></div>${rm.enabled?`<div class="goal-row"><span>تذكير الماء</span><strong>كل ${rm.waterMinutes} دقيقة</strong></div><div class="goal-row"><span>أوقات الوجبات</span><strong>${rm.mealTimes.join(' · ')||'—'}</strong></div><div class="goal-row"><span>وقت عدم الإزعاج</span><strong>${rm.quietStart} — ${rm.quietEnd}</strong></div>`:''}<p class="notice">تعمل التذكيرات أثناء فتح التطبيق في متصفح هذا الجهاز فقط، وتحتاج السماح بإشعارات المتصفح.</p></div><div class="card"><div class="card-head"><h2>أفراد العائلة</h2></div>${profiles.list.map(p=>`<div class="goal-row"><span><span class="avatar sm ${esc(p.color||'')}" style="display:inline-grid;width:26px;height:26px;font-size:12px;margin-left:8px;vertical-align:middle">${esc((p.name||'?').charAt(0))}</span>${esc(p.name)}${p.id===profiles.activeId?' (الحالي)':''}${p.id==='default'?' · يتزامن سحابيًا':' · محلي على هذا الجهاز'}</span><span class="actions">${p.id!==profiles.activeId?`<button class="text-button" data-action="switchProfile" data-id="${esc(p.id)}">تفعيل</button>`:''}<button class="text-button" data-action="renameProfile" data-id="${esc(p.id)}">إعادة تسمية</button>${profiles.list.length>1?`<button class="text-button danger" data-action="removeProfile" data-id="${esc(p.id)}">حذف</button>`:''}</span></div>`).join('')}<button class="button secondary" data-action="addProfile" style="margin-top:14px">+ إضافة فرد جديد</button><p class="notice">أضف أفراد عائلتك (زوجة، أبناء) ليتابع كل واحد وجباته وتمارينه بشكل منفصل على هذا الجهاز. الملف الرئيسي فقط يتزامن مع حسابك السحابي.</p></div><div><div class="card"><h2>المزامنة والنسخ الاحتياطية</h2><p id="syncDetail" class="notice">${esc(syncState)}</p><button class="button secondary" data-action="sync">مزامنة الآن</button><p class="sub">افتح نفس رابط التطبيق على الموبايل والكمبيوتر بنفس حساب ChatGPT. يتم دمج سجلات كل جهاز عند أول اتصال. احتفظ بنسخة شاملة للوجبات والمياه والمشي والتمارين والقياسات.</p><div class="quick-buttons">${button('تصدير نسخة JSON','export')}${button('استيراد ودمج نسخة','import',true)}</div><p class="notice">الاستيراد يدمج السجلات ويتجاهل التطابقات. سجلاتك الحالية وأهدافك لها الأولوية عند التعارض.</p></div><div class="card"><h2>استخدام التطبيق على الموبايل</h2><p class="sub">على iPhone، افتح الرابط في Safari ثم مشاركة ← إضافة إلى الشاشة الرئيسية.</p><p class="notice">المشي بإدخال يدوي، ولا يوجد ربط تلقائي بساعة أو Apple Health. السجلات والأهداف تتزامن تلقائيًا بين أجهزتك المتصلة بالحساب نفسه.</p></div></div></div>`}
function renderProfiles(){const el=$('#profileSwitcher');if(el)el.innerHTML=profiles.list.map(p=>`<button class="profile-chip ${p.id===profiles.activeId?'active':''}" data-action="switchProfile" data-id="${esc(p.id)}" title="${esc(p.name)}"><span class="avatar sm ${esc(p.color||'')}">${esc((p.name||'?').trim().charAt(0)||'?')}</span><span>${esc(p.name)}</span></button>`).join('')+`<button class="profile-chip add" data-action="addProfile" aria-label="إضافة فرد من العائلة">+ فرد جديد</button>`;const ap=activeProfile();const av=$('#activeAvatar');if(av)av.textContent=(ap.name||'?').trim().charAt(0)||'?';const nm=$('#activeProfileInfo');if(nm)nm.innerHTML=`${esc(ap.name)}<small>${ap.id==='default'?'رحلتك، خطوة بخطوة':'ملف محلي على هذا الجهاز'}</small>`}
function render(){if(!nav.some(n=>n[0]===view))view='today';$('#pageTitle').textContent=nav.find(n=>n[0]===view)[3];$('#navigation').innerHTML=nav.map(([id,i,l])=>`<a href="#${id}" class="${view===id?'active':''}" ${view===id?'aria-current="page"':''}>${icon(i)}<span>${l}</span></a>`).join('');$('#selectedDate').value=selected;$('#dateLabel').textContent=pretty(selected,{weekday:'long',day:'numeric',month:'long'});$('#weekStrip').innerHTML=Array.from({length:7},(_,i)=>shift(selected,i-3)).map(d=>{const active=['meals','water','walking','workouts'].some(k=>byDate(k,d).length);return `<button class="day ${d===selected?'selected':''}" data-action="date" data-date="${d}" aria-label="${pretty(d)}" ${d===selected?'aria-current="date"':''}><span>${pretty(d,{weekday:'short'})}</span><strong>${new Date(d+'T12:00:00').getDate()}</strong>${active?'<span class="dot"></span>':'<span style="height:8px"></span>'}</button>`}).join('');$('#content').innerHTML=({today:renderToday,meals:renderMeals,activity:renderActivity,workouts:renderWorkouts,nutrition:renderNutrition,progress:renderProgress,settings:renderSettings}[view])();renderProfiles();showSync(syncState);if(loadFailed)notify('تعذر قراءة البيانات المحفوظة. صدّرها من الإعدادات لحمايتها.',true)}
function input(name,label,value='',type='text',required=false,extra=''){return `<label class="field" for="f-${name}">${label}<input id="f-${name}" name="${name}" value="${esc(value??'')}" type="${type}" ${required?'required':''} ${extra}></label>`}
const number=(n,l,v='',required=false,min=0,step='any',max='')=>input(n,l,v,'number',required,`min="${min}" step="${step}" ${max!==''?`max="${max}"`:''}`);
const select=(n,l,choices,value)=>`<label class="field" for="f-${n}">${l}<select id="f-${n}" name="${n}">${[...new Set([...(value?[value]:[]),...choices])].map(x=>`<option value="${esc(x)}" ${x===value?'selected':''}>${esc(x)}</option>`).join('')}</select></label>`;
const textarea=(n,l,v)=>`<label class="field full" for="f-${n}">${l}<textarea id="f-${n}" name="${n}" maxlength="2000">${esc(v||'')}</textarea></label>`;
const timeNow=()=>new Date().toTimeString().slice(0,5);
function openForm(kind,record=null,repeat=false){formKind=kind;editing=repeat?null:record;$('#formError').textContent='';const r=record||{},date=repeat?selected:(r.date||selected);let html='',title='';const common=()=>input('date','التاريخ الفعلي',date,'date',true);if(kind==='meal'){title=editing?'تعديل الوجبة':'تسجيل وجبة';html=common()+select('name','الوجبة',['فطور','غداء','عشاء','سناك','قبل التمرين','بعد التمرين'],r.name||'فطور')+input('time','الوقت (اختياري)',repeat?'':r.time||'','time')+number('grams','وزن الطعام بالغرام (اختياري)',r.grams)+`<label class="field full">مكونات الوجبة<input name="food" value="${esc(r.food||'')}" maxlength="500" required></label>`+['calories','protein','carbs','fat'].map((k,i)=>number(k,['السعرات لكل الوجبة','بروتين الوجبة (غ)','كارب الوجبة (غ)','دهون الوجبة (غ)'][i],r[k],true)).join('')+'<p class="form-note">القيم تخص كامل الوجبة. لا تُحسب تلقائيًا من وزن الطعام.</p>'}else if(kind==='workout'){title=editing?'تعديل التمرين':'تسجيل تمرين';const eq=r.equipment||equipmentLibrary[0].id,eqDef=equipmentLibrary.find(x=>x.id===eq);html=common()+`<label class="field" for="f-equipment">الجهاز / المعدة<select id="f-equipment" name="equipment">${equipmentLibrary.map(e=>`<option value="${esc(e.id)}" ${e.id===eq?'selected':''}>${esc(e.name)}</option>`).join('')}</select></label>`+select('group','المجموعة العضلية',['صدر','ظهر','كتف','باي','تراي','رجل','بطن','سواعد','كامل الجسم','كارديو'],r.group||(eqDef&&eqDef.group!=='كامل الجسم'?eqDef.group:'صدر'))+`<label class="field full" for="f-exercise">اسم التمرين<input id="f-exercise" name="exercise" list="exerciseOptions" value="${esc(r.exercise||'')}" maxlength="120" required placeholder="اختر من اقتراحات الجهاز أو اكتب اسمًا آخر"></label><datalist id="exerciseOptions">${(eqDef?.exercises||[]).map(x=>`<option value="${esc(x)}">`).join('')}</datalist>`+number('duration','المدة بالدقائق (اختياري)',r.duration,false,1,1);for(let i=1;i<=4;i++){const s=r.sets?.[i-1];html+=`<p class="sets-title">الجولة ${i}${i===4?' — اختيارية':''}</p>`+number('w'+i,'الوزن (كجم)',s?.w??'',i<=3,0)+number('r'+i,'العدات',s?.r??'',i<=3,1,1)}html+=textarea('notes','ملاحظات التمرين',r.notes)}else if(kind==='nutrition'){title='بيانات خطتك الغذائية';const np=data.nutritionPlan||{},lastWeight=[...data.measurements].sort((a,b)=>a.date.localeCompare(b.date)).at(-1)?.weight;html=`<label class="field" for="f-gender">الجنس<select id="f-gender" name="gender"><option value="male" ${(np.gender||'male')==='male'?'selected':''}>ذكر</option><option value="female" ${np.gender==='female'?'selected':''}>أنثى</option></select></label>`+number('age','العمر',np.age,true,10,1,100)+number('height','الطول (سم)',np.height,true,100,.1,250)+number('weight','الوزن الحالي (كجم)',np.weight??lastWeight??'',true,30,.1,300)+`<label class="field" for="f-activity">مستوى النشاط<select id="f-activity" name="activity">${Object.entries(activityLabels).map(([k,l])=>`<option value="${k}" ${(np.activity||'moderate')===k?'selected':''}>${l}</option>`).join('')}</select></label>`+`<label class="field" for="f-goal">هدفك<select id="f-goal" name="goal">${Object.entries(goalLabels).map(([k,l])=>`<option value="${k}" ${(np.goal||'maintain')===k?'selected':''}>${l}</option>`).join('')}</select></label>`+'<p class="form-note">سنحسب سعراتك وماكروزك تلقائيًا (تنشيف أو تضخيم أو ثبات) ونقترح نموذج وجبات يمكن تطبيقه كهدف يومي.</p>'}else if(kind==='reminders'){title='تذكيرات المياه والطعام';const rm=data.reminders;html=`<label class="field checkbox-field full"><input type="checkbox" id="f-enabled" name="enabled" ${rm.enabled?'checked':''}> تفعيل التذكيرات أثناء فتح التطبيق</label>`+number('waterMinutes','التذكير بشرب الماء كل (دقيقة)',rm.waterMinutes,true,15,1,360)+input('mealTime1','تذكير الوجبة الأولى',rm.mealTimes[0]||'','time')+input('mealTime2','تذكير الوجبة الثانية',rm.mealTimes[1]||'','time')+input('mealTime3','تذكير الوجبة الثالثة',rm.mealTimes[2]||'','time')+input('mealTime4','تذكير رابع (اختياري)',rm.mealTimes[3]||'','time')+input('quietStart','بداية وقت عدم الإزعاج',rm.quietStart,'time',true)+input('quietEnd','نهاية وقت عدم الإزعاج',rm.quietEnd,'time',true)+'<p class="form-note">تعمل التذكيرات أثناء فتح التطبيق في متصفح هذا الجهاز، وتحتاج السماح بإشعارات المتصفح عند التفعيل.</p>'}else if(kind==='water'){title=editing?'تعديل كمية المياه':'تسجيل مياه';html=common()+input('time','الوقت',r.time||timeNow(),'time')+number('ml','الكمية (مل)',r.ml||'',true,1,1,10000)}else if(kind==='walking'){title='إجمالي المشي اليومي';const w=record||{...walkTotal(),date:selected};html=input('date','التاريخ الفعلي',w.date||selected,'date',true)+number('steps','إجمالي خطوات اليوم',w.steps||'',true,0,1,200000)+number('minutes','إجمالي الدقائق (اختياري)',w.minutes||'',false,0,1,1440)+number('distance','المسافة بالكيلومتر (اختياري)',w.distance||'',false,0,.01,500)+'<p class="form-note">سوف تُحدّث قراءة اليوم المحدد، ولن تُضاف الخطوات إلى القراءة السابقة.</p>'}else if(kind==='measurement'){title=editing?'تعديل القياس':'قياس جديد';html=common()+number('weight','الوزن (كجم)',r.weight,true,.1,.1,600)+[['bmi','BMI'],['bfr','دهون الجسم %'],['fatMass','كتلة الدهون كجم'],['muscleWeight','وزن العضلات كجم'],['water','ماء الجسم %'],['bmr','BMR'],['visceralFat','دهون حشوية'],['leanWeight','وزن دون دهون كجم']].map(([k,l])=>number(k,l+' (اختياري)',r[k])).join('')}else if(kind==='goals'){title='تعديل أهدافك';html=goalFields.map(([k,l])=>number(k,l,k==='goalWeight'?data.goalWeight:data.targets[k],false,k==='goalWeight'?.1:1,['steps','workoutDays','water'].includes(k)?1:'any',k==='workoutDays'?7:'')).join('')+'<p class="form-note">اترك الهدف فارغًا إن لم تحدده بعد.</p>'}else if(kind==='note'){title='ملاحظات اليوم';html=textarea('note','ملاحظات '+pretty(selected),data.dayNotes[selected])}$('#dialogTitle').textContent=title;$('#fields').innerHTML=html;$('#editor').showModal();$('#f-equipment')?.addEventListener('change',e=>{const lib=equipmentLibrary.find(x=>x.id===e.target.value);const dl=$('#exerciseOptions');if(dl)dl.innerHTML=(lib?.exercises||[]).map(x=>`<option value="${esc(x)}">`).join('')})}
function dateValid(d){if(!/^\d{4}-\d{2}-\d{2}$/.test(d||''))return false;const x=new Date(d+'T12:00:00');return !isNaN(x.getTime())&&shift(d,0)===d}
function submitRecord(fd){const next=structuredClone(data);if(fd.date&&!dateValid(fd.date))throw Error('اختر تاريخًا صحيحًا.');let r,key;const nullable=k=>fd[k]===''||fd[k]==null?null:num(fd[k]);if(formKind==='goals'){next.goalWeight=nullable('goalWeight');for(const [k] of goalFields)if(k!=='goalWeight')next.targets[k]=nullable(k)}else if(formKind==='note'){next.dayNotes[selected]=fd.note.trim()}else if(formKind==='nutrition'){const p={gender:fd.gender,age:num(fd.age),height:num(fd.height),weight:num(fd.weight),activity:fd.activity,goal:fd.goal};if(!p.age||!p.height||!p.weight)throw Error('أكمل العمر والطول والوزن.');next.nutritionPlan={...p,...computePlan(p),generatedAt:today()}}else if(formKind==='reminders'){const mealTimes=[fd.mealTime1,fd.mealTime2,fd.mealTime3,fd.mealTime4].filter(Boolean);next.reminders={enabled:!!fd.enabled,waterMinutes:num(fd.waterMinutes),mealTimes,quietStart:fd.quietStart,quietEnd:fd.quietEnd};if(next.reminders.enabled&&'Notification' in window&&Notification.permission==='default')Notification.requestPermission()}else{const base={...(editing||{}),id:editing?.id||uid(),date:fd.date};if(formKind==='meal'){key='meals';r={...base,name:fd.name,food:fd.food.trim(),time:fd.time,grams:nullable('grams'),...Object.fromEntries(['calories','protein','carbs','fat'].map(k=>[k,num(fd[k])]))};if(!r.food)throw Error('اكتب مكونات الوجبة.')}else if(formKind==='workout'){key='workouts';const sets=[];for(let i=1;i<=4;i++){if(i===4&&fd.w4===''&&fd.r4==='')continue;if(fd['w'+i]===''||fd['r'+i]==='')throw Error('أكمل الوزن والعدات لكل جولة مستخدمة.');sets.push({w:num(fd['w'+i]),r:num(fd['r'+i])})}r={...base,exercise:fd.exercise.trim(),group:fd.group,equipment:fd.equipment||null,duration:nullable('duration'),notes:fd.notes,sets};if(!r.exercise)throw Error('اكتب اسم التمرين.')}else if(formKind==='water'){key='water';r={...base,ml:num(fd.ml),time:fd.time}}else if(formKind==='walking'){key='walking';r={...base,steps:num(fd.steps),minutes:nullable('minutes'),distance:nullable('distance')};next.walking=next.walking.filter(x=>x.date!==r.date&&x.id!==editing?.id)}else{key='measurements';r={...base,weight:num(fd.weight),...Object.fromEntries(['bmi','bfr','fatMass','muscleWeight','water','bmr','visceralFat','leanWeight'].map(k=>[k,nullable(k)]))}}const i=next[key].findIndex(x=>x.id===r.id);if(i>=0)next[key][i]=r;else next[key].push(r)}validate(next);if(commit(next)){if(fd.date)selected=fd.date;$('#editor').close();render()}}
function validate(d){const positive=x=>typeof x==='number'&&Number.isFinite(x)&&x>=0;for(const k of ['meals','workouts','water','walking','measurements']){if(!Array.isArray(d[k])||d[k].length>50000)throw Error('حجم السجل أو تنسيقه غير صالح.');for(const r of d[k]){if(!r||!dateValid(r.date)||typeof r.id!=='string')throw Error('تاريخ أو تعريف سجل غير صالح.');if(k==='meals'&&(!['name','food'].every(f=>typeof r[f]==='string')||!['calories','protein','carbs','fat'].every(f=>positive(r[f]))))throw Error('قيم الوجبات غير صالحة.');if(k==='workouts'&&(typeof r.exercise!=='string'||typeof r.group!=='string'||(r.equipment!=null&&typeof r.equipment!=='string')||!Array.isArray(r.sets)||!r.sets.length||r.sets.some(s=>!positive(s.w)||!positive(s.r)||s.r<1||!Number.isInteger(s.r))))throw Error('قيم جولات التمرين غير صالحة.');if(k==='water'&&(!positive(r.ml)||!r.ml))throw Error('كمية مياه غير صالحة.');if(k==='walking'&&(!positive(r.steps)||!Number.isInteger(r.steps)||['minutes','distance'].some(f=>r[f]!=null&&!positive(r[f]))))throw Error('قيم المشي غير صالحة.');if(k==='measurements'&&(!positive(r.weight)||!r.weight||['bmi','bfr','fatMass','muscleWeight','water','bmr','visceralFat','leanWeight'].some(f=>r[f]!=null&&!positive(r[f]))))throw Error('قياس غير صالح.')}}if(d.goalWeight!=null&&(!positive(d.goalWeight)||!d.goalWeight))throw Error('هدف الوزن غير صالح.');if(!d.targets||typeof d.targets!=='object'||Object.values(d.targets).some(v=>v!=null&&!positive(v)))throw Error('أهداف غير صالحة.');if(d.targets.workoutDays!=null&&(!Number.isInteger(d.targets.workoutDays)||d.targets.workoutDays>7))throw Error('أيام التمرين من ١ إلى ٧.');if(!d.dayNotes||typeof d.dayNotes!=='object'||Array.isArray(d.dayNotes)||Object.entries(d.dayNotes).some(([k,v])=>!dateValid(k)||typeof v!=='string'))throw Error('ملاحظات غير صالحة.');if(d.nutritionPlan!=null){const np=d.nutritionPlan;if(typeof np!=='object'||Array.isArray(np))throw Error('بيانات الخطة الغذائية غير صالحة.');for(const f of ['age','height','weight','calories','protein','carbs','fat','bmr','tdee'])if(np[f]!=null&&!positive(np[f]))throw Error('بيانات الخطة الغذائية غير صالحة.')}if(d.reminders){const rm=d.reminders;if(typeof rm!=='object'||Array.isArray(rm)||typeof rm.enabled!=='boolean')throw Error('إعدادات التذكيرات غير صالحة.');if(!Number.isInteger(rm.waterMinutes)||rm.waterMinutes<15||rm.waterMinutes>360)throw Error('مدة تذكير المياه يجب أن تكون بين ١٥ و٣٦٠ دقيقة.');if(!Array.isArray(rm.mealTimes)||rm.mealTimes.length>8||rm.mealTimes.some(t=>!timeValid(t)))throw Error('أوقات تذكير الطعام غير صالحة.');if(!timeValid(rm.quietStart)||!timeValid(rm.quietEnd))throw Error('وقت السكون غير صالح.')}}
function canonical(r){return JSON.stringify(Object.keys(r).filter(k=>k!=='id').sort().map(k=>[k,r[k]]))}
function mergeData(current,incoming){const out=structuredClone(current);let count=0;for(const k of ['meals','workouts','water','walking','measurements']){const ids=new Set(out[k].map(x=>x.id)),values=new Set(out[k].map(canonical));for(const r of incoming[k]){if(ids.has(r.id)||values.has(canonical(r))||(k==='walking'&&out[k].some(x=>x.date===r.date)))continue;out[k].push(r);ids.add(r.id);values.add(canonical(r));count++}}out.dayNotes={...incoming.dayNotes,...current.dayNotes};for(const k of Object.keys(out.targets))if(out.targets[k]==null&&incoming.targets[k]!=null)out.targets[k]=incoming.targets[k];if(out.goalWeight==null)out.goalWeight=incoming.goalWeight;return {out,count}}
function downloadBackup(){const raw=loadFailed?localStorage.getItem(storageKey(profiles.activeId)):JSON.stringify(data,null,2);const url=URL.createObjectURL(new Blob([raw||''],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`fitness-backup-${activeProfile().name}-${today()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('تم تجهيز النسخة الاحتياطية للتنزيل')}
function timerText(){const seconds=Math.max(0,Math.ceil((timerEnd-Date.now())/1000));return `${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`}
function startTimer(seconds){clearInterval(timerHandle);timerEnd=Date.now()+seconds*1000;const tick=()=>{if($('#timer'))$('#timer').textContent=timerText();if(Date.now()>=timerEnd){clearInterval(timerHandle);timerEnd=0;notify('انتهت فترة الراحة')}};tick();timerHandle=setInterval(tick,250)}
function switchProfile(id){if(id===profiles.activeId||!profiles.list.some(p=>p.id===id))return;profiles.activeId=id;saveProfiles();const r=loadData();data=r.d;loadFailed=r.failed;selected=today();view='today';location.hash='today';if(id==='default'){syncState='جارٍ الاتصال…';syncNow()}else{syncState='ملف محلي على هذا الجهاز فقط';showSync(syncState)}render();notify(`تم التبديل إلى ${activeProfile().name}`)}
function addProfile(){const name=prompt('اسم الفرد الجديد (مثلاً: ماما، أخوي، ابني)');if(!name||!name.trim())return;const id=uid();profiles.list.push({id,name:name.trim().slice(0,40),color:PALETTE[profiles.list.length%PALETTE.length]});saveProfiles();switchProfile(id)}
function renameProfile(id){const p=profiles.list.find(x=>x.id===id);if(!p)return;const name=prompt('الاسم الجديد',p.name);if(!name||!name.trim())return;p.name=name.trim().slice(0,40);saveProfiles();render()}
function removeProfile(id){if(profiles.list.length<=1)return notify('لازم يبقى فرد واحد على الأقل.',true);const p=profiles.list.find(x=>x.id===id);if(!p)return;if(!confirm(`حذف "${p.name}" وكل بياناته المحفوظة على هذا الجهاز؟ لا يمكن التراجع.`))return;localStorage.removeItem(storageKey(id));profiles.list=profiles.list.filter(x=>x.id!==id);if(profiles.activeId===id){profiles.activeId=profiles.list[0].id;const r=loadData();data=r.d;loadFailed=r.failed;selected=today();view='today'}saveProfiles();render();notify('تم حذف الفرد وبياناته من هذا الجهاز')}
function setDate(d){if(dateValid(d)){selected=d;render()}}
const kinds={meals:'meal',workouts:'workout',measurements:'measurement',water:'water',walking:'walking'};
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action;if(['meal','workout','water','walking','measurement','goals','note','nutrition','reminders'].includes(a))return openForm(a);if(a==='settings'){location.hash='settings';view='settings';render()}else if(a==='close')$('#editor').close();else if(a==='previous')setDate(shift(selected,-1));else if(a==='next')setDate(shift(selected,1));else if(a==='today')setDate(today());else if(a==='date')setDate(el.dataset.date);else if(a==='range'){range=num(el.dataset.range);render()}else if(a==='water250'||a==='water500'){const next=structuredClone(data);next.water.push({id:uid(),date:selected,ml:a==='water250'?250:500,time:timeNow()});commit(next,'تم تسجيل المياه')}else if(a==='edit'||a==='repeat'){const r=data[el.dataset.key]?.find(x=>x.id===el.dataset.id);if(r)openForm(kinds[el.dataset.key],r,a==='repeat')}else if(a==='delete'){if(confirm('حذف هذا السجل؟')){const next=structuredClone(data);next[el.dataset.key]=next[el.dataset.key].filter(x=>x.id!==el.dataset.id);commit(next,'تم حذف السجل')}}else if(a==='sync')syncNow();else if(a==='export')downloadBackup();else if(a==='import')$('#importFile').click();else if(a==='timer60')startTimer(60);else if(a==='timer90')startTimer(90);else if(a==='timerStop'){clearInterval(timerHandle);timerEnd=0;if($('#timer'))$('#timer').textContent='00:00'}else if(a==='applyNutrition'){const np=data.nutritionPlan;if(!np||!np.calories)return;const next=structuredClone(data);next.targets={...next.targets,calories:np.calories,protein:np.protein,carbs:np.carbs,fat:np.fat};commit(next,'تم تطبيق الخطة الغذائية كهدف يومي')}else if(a==='switchProfile')switchProfile(el.dataset.id);else if(a==='addProfile')addProfile();else if(a==='renameProfile')renameProfile(el.dataset.id);else if(a==='removeProfile')removeProfile(el.dataset.id)});
$('#recordForm').addEventListener('submit',e=>{e.preventDefault();if(!e.target.reportValidity())return;try{submitRecord(Object.fromEntries(new FormData(e.target)))}catch(err){$('#formError').textContent=err.message||'راجع البيانات ثم حاول مجددًا.'}});
$('#selectedDate').addEventListener('change',e=>setDate(e.target.value));
$('#importFile').addEventListener('change',async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>20000000)throw Error('الملف أكبر من ٢٠ ميجابايت.');const incoming=migrate(JSON.parse(await file.text()));validate(incoming);const {out,count}=mergeData(data,incoming);if(confirm(`سيتم دمج ${count} سجل جديد مع الحفاظ على بياناتك الحالية. متابعة؟`)){if(loadFailed){if(!confirm('البيانات القديمة تعذر قراءتها. تأكد من تصديرها أولًا. هل تريد اعتماد النسخة المستوردة؟'))return;loadFailed=false}commit(out,`تم استيراد ${count} سجل جديد`)}}catch(err){notify(err.message||'الملف غير صالح.',true)}finally{e.target.value=''}});
window.addEventListener('hashchange',()=>{view=location.hash.slice(1)||'today';render()});
window.addEventListener('storage',e=>{if(e.key===OUTBOX)syncNow()});
const OUTBOX=KEY+'-outbox-v3',IMPORTED=KEY+'-cloud-import-v3';
let syncBusy=false,syncState=profiles.activeId==='default'?'جارٍ الاتصال…':'ملف محلي على هذا الجهاز فقط',lastSync='';
const collectionKeys=['meals','workouts','measurements','water','walking'];
function pending(){try{return JSON.parse(localStorage.getItem(OUTBOX)||'[]')}catch{throw Error('تعذر قراءة التغييرات المعلقة. صدّر نسخة احتياطية.')}}
function difference(before,after){const changes=[];for(const key of collectionKeys){for(const r of after[key]){const old=before[key].find(x=>x.id===r.id);if(!old||JSON.stringify(old)!==JSON.stringify(r))changes.push({key,id:r.id,value:r})}for(const r of before[key])if(!after[key].some(x=>x.id===r.id))changes.push({key,id:r.id,value:null})}for(const key of ['targets','dayNotes'])for(const field of new Set([...Object.keys(before[key]),...Object.keys(after[key])]))if(before[key][field]!==after[key][field])changes.push({key,field,value:after[key][field]??null});if(before.goalWeight!==after.goalWeight)changes.push({key:'goalWeight',value:after.goalWeight});return changes}
function applyChanges(base,ops){const next=structuredClone(base);for(const op of ops)for(const change of op.changes){const {key,id,value,field}=change;if(collectionKeys.includes(key)){next[key]=next[key].filter(x=>x.id!==id&&!(key==='walking'&&value&&x.date===value.date));if(value)next[key].push(value)}else if(key==='goalWeight')next.goalWeight=value;else if(key==='targets'||key==='dayNotes'){if(value===null&&key==='dayNotes')delete next[key][field];else next[key][field]=value}}return next}
function showSync(text){syncState=text;const el=document.querySelector('.local-badge');if(el)el.textContent=text;const status=document.querySelector('#syncDetail');if(status)status.textContent=text+(lastSync?' · آخر مزامنة '+lastSync:'')}
function commit(next,message='تم الحفظ'){if(loadFailed){notify('تعذر قراءة سجلات هذا الجهاز. صدّرها قبل المتابعة.',true);return false}try{const isDefault=profiles.activeId==='default';if(isDefault){const changes=difference(data,next);if(changes.length){const queue=pending();queue.push({id:uid(),changes});localStorage.setItem(OUTBOX,JSON.stringify(queue))}}data=next;try{localStorage.setItem(storageKey(profiles.activeId),JSON.stringify(next))}catch{}render();if(isDefault){showSync('تغييرات تنتظر المزامنة');notify(message+' — جارٍ المزامنة');syncNow()}else notify(message);return true}catch(err){notify(err.message||'تعذر حفظ التغيير.',true);return false}}
async function requestState(method='GET',body){const r=await fetch('/api/fitness-state',{method,credentials:'same-origin',cache:'no-store',headers:body?{'content-type':'application/json'}:{},body:body?JSON.stringify(body):undefined});if(r.status===401)throw Error('سجّل الدخول بنفس حسابك لإكمال المزامنة');if(r.status===409)return {conflict:true};if(!r.ok)throw Error(r.status===413?'حجم البيانات كبير؛ لم تكتمل المزامنة':'تعذر الاتصال؛ التغييرات محفوظة على هذا الجهاز');return r.json()}
async function performSync(){if(syncBusy||loadFailed||profiles.activeId!=='default')return;syncBusy=true;showSync('جارٍ المزامنة…');try{for(let attempt=0;attempt<4;attempt++){const remote=await requestState();let base=remote.data?migrate(remote.data):defaults();validate(base);
 if(!localStorage.getItem(IMPORTED)){const combined=mergeData(base,data).out;const changes=difference(base,combined);if(changes.length){const list=pending();list.unshift({id:uid(),changes});localStorage.setItem(OUTBOX,JSON.stringify(list))}localStorage.setItem(IMPORTED,'1')}
 const batch=pending(),candidate=applyChanges(base,batch);validate(candidate);
 if(batch.length){const answer=await requestState('PUT',{data:candidate,revision:remote.revision});if(answer.conflict)continue;const sent=new Set(batch.map(x=>x.id));const remaining=pending().filter(x=>!sent.has(x.id));localStorage.setItem(OUTBOX,JSON.stringify(remaining));data=applyChanges(candidate,remaining)}else data=base;
 localStorage.setItem(KEY,JSON.stringify(data));lastSync=new Date().toLocaleTimeString('ar-EG',{hour:'2-digit',minute:'2-digit'});render();showSync(pending().length?'تغييرات تنتظر المزامنة':'متزامن مع حسابك');return;
 }showSync('جارٍ دمج تحديثات الأجهزة؛ سنعيد المحاولة');}catch(err){showSync(err.message||'تعذر الاتصال؛ سنعيد المزامنة تلقائيًا')}finally{syncBusy=false}}
function syncNow(){if(navigator.locks)return navigator.locks.request('fitness-cloud-sync',{ifAvailable:true},lock=>lock?performSync():undefined);return performSync()}
window.addEventListener('online',()=>syncNow());window.addEventListener('focus',()=>syncNow());document.addEventListener('visibilitychange',()=>{if(!document.hidden)syncNow()});setInterval(()=>{if(!document.hidden)syncNow()},15000);

function withinQuiet(hhmm,start,end){if(!start||!end)return false;return start<end?(hhmm>=start&&hhmm<end):(hhmm>=start||hhmm<end)}
function sendReminder(title,body){if('Notification' in window&&Notification.permission==='granted'){try{new Notification(title,{body,icon:'icon-192.png'});return}catch{}}notify(`${title} — ${body}`)}
let lastWaterPing=Number(localStorage.getItem(KEY+'-last-water-ping')||0),firedMealKey='';
function checkReminders(){const rm=data.reminders;if(!rm||!rm.enabled)return;const now=new Date(),hhmm=now.toTimeString().slice(0,5);if(withinQuiet(hhmm,rm.quietStart,rm.quietEnd))return;if(rm.waterMinutes&&Date.now()-lastWaterPing>=rm.waterMinutes*60000){lastWaterPing=Date.now();localStorage.setItem(KEY+'-last-water-ping',String(lastWaterPing));sendReminder('وقت شرب الماء 💧','اشرب كوب ماء الآن وسجّله في التطبيق.')}const todayKey=today()+'|'+hhmm;if(rm.mealTimes.includes(hhmm)&&firedMealKey!==todayKey){firedMealKey=todayKey;sendReminder('وقت الوجبة 🍽️','حان وقت وجبتك — لا تنسَ تسجيلها.')}}
setInterval(checkReminders,60000);

view=location.hash.slice(1)||'today';render();

syncNow();
